body:
Wow, very interesting and kinda weird behavior. After some testing, I think the `emit_signal` are called in the right order but the signals are not received in this order when they are called on the same frame. Anyway, I would not worry too much about the order then. I just suggest you emit the `button_up` only when `pressed_down_with_focus` is true and not necessary, remove the code duplication.

Something like that:
```
if (p_event->is_pressed() && (mouse_button.is_null() || status.hovering)) {
	status.press_attempt = true;
	status.pressing_inside = true;
	if (!status.pressed_down_with_focus) {
		status.pressed_down_with_focus = true;
		emit_signal(SNAME("button_down"));
	}
}

bool simulate_release = false;
if (status.press_attempt && status.pressing_inside) {
	if (toggle_mode) {
		bool is_pressed = p_event->is_pressed();
		if ((is_pressed && action_mode == ACTION_MODE_BUTTON_PRESS) || (!is_pressed && action_mode == ACTION_MODE_BUTTON_RELEASE)) {
			if (action_mode == ACTION_MODE_BUTTON_PRESS) {
				simulate_release = true;
			}
			status.pressed = !status.pressed;
			_unpress_group();
			if (button_group.is_valid()) {
				button_group->emit_signal(SceneStringName(pressed), this);
			}
			_toggled(status.pressed);
			_pressed();
		}
	} else {
		if ((p_event->is_pressed() && action_mode == ACTION_MODE_BUTTON_PRESS) || (!p_event->is_pressed() && action_mode == ACTION_MODE_BUTTON_RELEASE)) {
			_pressed();
		}
	}
}

if (simulate_release || !p_event->is_pressed()) {
	status.press_attempt = false;
	status.pressing_inside = false;
	if (status.pressed_down_with_focus) {
		status.pressed_down_with_focus = false;
		emit_signal(SNAME("button_up"));
	}
}
```

